using System;
using Pantheon.Game.Presentation;
using Xunit;

namespace Pantheon.Tests.Game;

/// <summary>Bounds-safe region lookups in Terrain3D's generated shader.</summary>
public sealed class Terrain3DShaderPatchTests
{
    // Excerpt of the shader generated by Terrain3D 1.0.2.
    private const string Terrain3DExcerpt = """
        ivec3 get_index_coord(const vec2 uv, const int search) {
        			pos = ivec2(floor((r_uv) * _region_texel_size)) + (_region_map_size / 2);
        			bounds = int(uint(pos.x | pos.y) < uint(_region_map_size));
        			layer_index = (_region_map[ pos.y * _region_map_size + pos.x ] * bounds - 1);
        }
        vec3 get_index_uv(const vec2 uv2) {
        	int bounds = int(uint(pos.x | pos.y) < uint(_region_map_size));
        	int layer_index = _region_map[ pos.y * _region_map_size + pos.x ] * bounds - 1;
        	return vec3(uv2 - _region_locations[layer_index], float(layer_index));
        }
        """;

    [Fact]
    public void Apply_ClampsEveryRegionMapLookup()
    {
        var expected = Terrain3DExcerpt.Replace(Terrain3DShaderPatch.RegionMapLookup, Terrain3DShaderPatch.ClampedRegionMapLookup, StringComparison.Ordinal);

        var patched = Terrain3DShaderPatch.Apply(Terrain3DExcerpt);

        Assert.Equal(expected, patched);
        Assert.Equal(2, CountOccurrences(expected, Terrain3DShaderPatch.ClampedRegionMapLookup));
        Assert.DoesNotContain(Terrain3DShaderPatch.RegionMapLookup, expected, StringComparison.Ordinal);
    }

    [Fact]
    public void Apply_RejectsShadersWithoutTheExpectedLookup()
    {
        var alreadyPatched = Terrain3DShaderPatch.Apply(Terrain3DExcerpt);

        Assert.Null(Terrain3DShaderPatch.Apply("shader_type spatial;\nvoid fragment() { ALBEDO = vec3(1.0); }\n"));
        Assert.NotNull(alreadyPatched);
        Assert.Null(Terrain3DShaderPatch.Apply(alreadyPatched));
    }

    /// <summary>Counts non-overlapping occurrences of <paramref name="value"/> in <paramref name="text"/>.</summary>
    private static int CountOccurrences(string text, string value)
    {
        var count = 0;
        for (var index = text.IndexOf(value, StringComparison.Ordinal); index >= 0; index = text.IndexOf(value, index + value.Length, StringComparison.Ordinal))
        {
            count++;
        }

        return count;
    }
}
